package org.rabochaya.projects;
import java.io.*;import java.security.*;import java.util.*;
/** Project-private named snapshots; stores composition metadata, never map/cache/KML payloads. */
public final class MapCompositionPresets {
 public static final int MAX_PRESETS=16,MAX_NAME=80,MAX_BYTES=524288;private static final int MAGIC=0x524b5053;
 public final long project;public final String revision;public final List<Entry> entries;
 public static final class Entry {public final String name;public final MapComposition composition;private Entry(String name,MapComposition composition){this.name=name;this.composition=composition;}}
 public MapCompositionPresets(long project){this(project,Collections.<Entry>emptyList(),UUID.randomUUID().toString());}
 private MapCompositionPresets(long project,List<Entry> entries,String revision){if(project<=0||entries.size()>MAX_PRESETS||revision==null||!revision.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"))throw new IllegalArgumentException("Недопустимая библиотека наборов");this.project=project;this.revision=revision;this.entries=Collections.unmodifiableList(new ArrayList<>(entries));}
 private static String name(String raw){if(raw==null)throw new IllegalArgumentException("Укажите название набора");String value=raw.trim();if(value.isEmpty()||value.length()>MAX_NAME)throw new IllegalArgumentException("Название набора: от 1 до "+MAX_NAME+" знаков");for(int i=0;i<value.length();i++)if(Character.isISOControl(value.charAt(i)))throw new IllegalArgumentException("В названии набора недопустимы управляющие знаки");return value;}
 public Entry find(String name){for(Entry e:entries)if(e.name.equals(name))return e;return null;}
 public MapCompositionPresets add(String raw,MapComposition composition){String name=name(raw);if(composition==null||composition.project!=project)throw new IllegalArgumentException("Набор относится к другому проекту");if(find(name)!=null)throw new IllegalArgumentException("Набор с таким названием уже есть");if(entries.size()>=MAX_PRESETS)throw new IllegalArgumentException("Предел — "+MAX_PRESETS+" наборов");List<Entry> next=new ArrayList<>(entries);next.add(new Entry(name,composition));return new MapCompositionPresets(project,next,UUID.randomUUID().toString());}
 public MapCompositionPresets remove(String name){Entry e=find(name);if(e==null)throw new IllegalArgumentException("Набор больше не найден");List<Entry> next=new ArrayList<>(entries);next.remove(e);return new MapCompositionPresets(project,next,UUID.randomUUID().toString());}
 private static byte[] digest(byte[] body){try{return MessageDigest.getInstance("SHA-256").digest(body);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public byte[] encode()throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(MAGIC);out.writeInt(1);out.writeLong(project);out.writeUTF(revision);out.writeInt(entries.size());for(Entry e:entries){byte[] composition=e.composition.encode();if((long)bytes.size()+composition.length+e.name.length()*3+39>MAX_BYTES)throw new IOException("Слишком большая библиотека наборов");out.writeUTF(e.name);out.writeInt(composition.length);out.write(composition);}}byte[] body=bytes.toByteArray();if(body.length+32>MAX_BYTES)throw new IOException("Слишком большая библиотека наборов");bytes.write(digest(body));return bytes.toByteArray();}
 public static MapCompositionPresets decode(byte[] all,long project)throws IOException{if(all==null||all.length<90||all.length>MAX_BYTES)throw new IOException("Недопустимый размер библиотеки наборов");byte[] body=Arrays.copyOf(all,all.length-32);if(!MessageDigest.isEqual(digest(body),Arrays.copyOfRange(all,all.length-32,all.length)))throw new IOException("Библиотека наборов повреждена");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(body))){if(in.readInt()!=MAGIC||in.readInt()!=1||in.readLong()!=project)throw new IOException("Библиотека относится к другому проекту или версии");String revision=in.readUTF();int count=in.readInt();if(count<0||count>MAX_PRESETS)throw new IOException("Недопустимое число наборов");MapCompositionPresets result=new MapCompositionPresets(project);for(int i=0;i<count;i++){String name=in.readUTF();if(!name.equals(name(name)))throw new IOException("Неканоническое название набора");int length=in.readInt();if(length<52||length>131072||length>in.available())throw new IOException("Недопустимый снимок набора");byte[] composition=new byte[length];in.readFully(composition);result=result.add(name,MapComposition.decode(composition,project));}if(in.available()!=0)throw new IOException("Лишние данные библиотеки наборов");return new MapCompositionPresets(project,result.entries,revision);}catch(IllegalArgumentException e){throw new IOException("Недопустимая библиотека наборов",e);}}
}
